        totalPublications: 91,
        bio:
          "A short biography of Dr. Md Abdur Rahim. He received his PhD in 2020 from the Graduate School of Computer Science and Engineering at The University of Aizu in Fukushima, Japan. He completed his Bachelor of Science (Honours) and Master of Science (M.Sc.) degrees in Computer Science and Engineering at the University of Rajshahi in Bangladesh, graduating in 2008 and 2009, respectively. Currently, he serves as a professor and the head of the Department of Computer Science and Engineering at Pabna University of Science and Technology in Pabna 6600, Bangladesh. His research interests encompass human-computer interaction, pattern recognition, computer vision and image processing, human recognition, and machine intelligence. He has published numerous papers in major journals (SCI and SCIE indexed) and conferences, as well as reviews for several SCI/SCIE indexed journals and international conferences. He is actively involved in various social and extracurricular activities. Currently, he serves in several key roles, including Director of the ICT Cell, Training Coordinator of the PUSTCSE Digital Skills Training Program under the ICT Division, Technical Focal Point for the GST Admission Test at PUST, Convener of various administrative subcommittees, and General Secretary of the PUST Teachers' Association. In addition, he has previously held the following positions: a) Secretary, Teacher-Officer Club, PUST b) Joint Secretary, Teacher's Association, PUST c) Member, Teacher's Association, PUST d) Assistant Proctor, PUST e) Member, Campus Network Sub-Project, BdREN, PUST f) Coordinator, MCSE Evening Program, CSE, PUST.",
