        totalPublications: 43,
        bio: 'Dr. Md. Shahajan Ali (M. S. Ali) is a Professor in the Department of Physics at Pabna University of Science and Technology. Previously, he worked as a Lecturer in the Department of Natural Sciences at Daffodil International University, Dhaka. Dr. M. S. Ali received his B.Sc. (Hons.) and M.Sc. (Thesis-Group B - Solid State Physics) degrees in Physics from the University of Rajshahi in 2009 and 2010, respectively, and earned his Ph.D. in Energy Materials Science from the Department of Engineering, Integrated Graduate School of Medicine, Engineering and Agriculture Sciences, University of Yamanashi, Japan in 2021. During his doctoral study, he collaborated with thirteen national and international universities and research centers on single crystal growth of oxide solid electrolyte materials for next-generation all-solid-state batteries.',
