        bio: 'Dr. Md. Hafijur Rahman is an Associate Professor of the Department of Physics at Pabna University of Science and Technology. He received his Doctor of Philosophy (Ph.D) degree from the Department of Physics at Pabna University of Science and Technology in 2022. Previously, he completed his B.Sc.(Hons.) and M.Sc.(Thesis) degrees in Applied Physics and Electronic Engineering from the University of Rajshahi, Rajshahi, Bangladesh in 2007 and 2008, respectively. His research interests focus on Solid State Physics, Condensed Matter Physics, Material Science, Thin Film, Porous Silicon, Semiconductor Devices, Electronic and Optoelectronic Device Fabrication, and Nanomaterials for Solar Cell Applications.',
