        bio:
          'Dr. Mohammad Tofajjol Hossen Bhuiyan is an Assistant Professor of Physics at Pabna University of Science and Technology (PUST), Pabna, Bangladesh. He completed his Bachelor of Science [BSc (Honours)] in Physics from Shahjalal University of Science and Technology (SUST), Sylhet, Bangladesh, with excellent CGPA (3.82 out of 4.00) and a distinction award. He subsequently completed his Master of Science [MS (Thesis)] in Physics from the same university with outstanding CGPA (3.99 out of 4.00) and a distinction award. In recognition of his outstanding academic achievements, he received the Chancellor’s Gold Medal and the Vice-Chancellor’s Award at the 3rd Convocation of SUST in 2020. The Chancellor’s Gold Medal was awarded in recognition of his highest overall academic achievement among all the graduates of the university, while the Vice-Chancellor’s Award recognized his highest CGPA at the master’s level in the Faculty of Science for the 2007–2008 academic session. Dr. Bhuiyan began his academic career as a Lecturer of Physics at the World University of Bangladesh (WUB), Dhaka in 2012. He later joined the Designated Reference Institute of Chemical Measurement (DRiCM) under the Bangladesh Council of Scientific and Industrial Research (BCSIR) as a Scientific Officer (SO). In 2014, he joined Pabna University of Science and Technology (PUST) as a Lecturer in Physics. Through his academic and professional career, he has remained actively engaged in teaching, research, and higher education. In 2019, Dr. Bhuiyan went to China under the Chinese Government Scholarship (CSC) to pursue his PhD. However, due to the COVID-19 pandemic, he returned to Bangladesh and later cancelled the admission at the University of Science and Technology of China (USTC). In 2022, he was awarded the Monash Graduate Scholarship (MGS), the Monash International Tuition Scholarship (MITS), and the AINSE Post Graduate Research Award (PGRA) to pursue his PhD at Monash University, Australia. He successfully completed his doctoral studies and was awarded his PhD degree by Monash University in 2026. Dr. Bhuiyan has authored numerous research articles in international peer-reviewed journals. His research interests encompass two-dimensional (2D) materials, condensed matter physics, solid-state physics, nanostructures and nanoelectronics, quantum electronics, and magnetism. His research focuses on the fundamental properties and potential applications of advanced materials and nanoscale systems.',
